ALTER TABLE public.members ADD COLUMN cnp text, ADD COLUMN birth_date date, ADD COLUMN profession text, ADD COLUMN workplace text, ADD COLUMN county text, ADD COLUMN city text, ADD COLUMN activity_type text, ADD COLUMN education text, ADD COLUMN mother_tongue text, ADD COLUMN other_languages text, ADD COLUMN motivation text, ADD COLUMN gdpr_consent boolean NOT NULL DEFAULT false, ADD COLUMN general_consent boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.validate_membership_fields() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN
IF NEW.cnp IS NOT NULL THEN
IF NEW.cnp !~ '^[1-9][0-9]{12}$' OR NEW.birth_date IS NULL OR NEW.birth_date > CURRENT_DATE OR NEW.gdpr_consent IS NOT TRUE OR NEW.general_consent IS NOT TRUE THEN RAISE EXCEPTION 'Date de adeziune nevalide'; END IF;
IF char_length(NEW.full_name) NOT BETWEEN 2 AND 100 OR NEW.email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR char_length(NEW.email) > 255 OR char_length(COALESCE(NEW.address,'')) NOT BETWEEN 3 AND 500 OR char_length(COALESCE(NEW.motivation,'')) NOT BETWEEN 10 AND 2000 OR char_length(COALESCE(NEW.city,'')) NOT BETWEEN 2 AND 80 OR char_length(COALESCE(NEW.county,'')) NOT BETWEEN 2 AND 50 OR NEW.activity_type NOT IN ('activ','simpatizant') OR char_length(COALESCE(NEW.profession,'')) > 100 OR char_length(COALESCE(NEW.workplace,'')) > 150 OR char_length(COALESCE(NEW.other_languages,'')) > 300 THEN RAISE EXCEPTION 'Date de adeziune incomplete sau prea lungi'; END IF;
END IF; RETURN NEW; END; $$;
CREATE TRIGGER validate_membership_fields BEFORE INSERT OR UPDATE ON public.members FOR EACH ROW EXECUTE FUNCTION public.validate_membership_fields();